                                                 Ogre::PF_R8G8B8, false, 1, mipmaps);
                } else {
                    finalImage.loadDynamicImage(image.getData(), image.getWidth(), image.getHeight(), 1,
                                                 Ogre::PF_R8G8B8, false, 1, 0);
