#pragma once
#include <boost/type_traits.hpp>
#include "reflection/object.h"

class ArchiveBinder;

namespace RBX
{
	class IReferenceBinder;

	// NOTE: may not be intended for this file
	class IIDREF
	{
		friend class MergeBinder;
		friend class ::ArchiveBinder;

	private:
