	void __cdecl _AFX_FUNCNAME(FormatMessage)( _In_ UINT nFormatID, ... );

#if defined(_AFX)
	void __cdecl FormatMessage( _In_ _Printf_format_string_ PCXSTR pszFormat, ... );

