		if (xmlNode->firstChild())
		{
			for (const XmlElement* child = xmlNode->firstChild(); child != NULL; child = child->nextSibling())
			{
				stream << '\n';
				serialize(child, depth + 1);
			}
			stream << '\n';
			writeCloseTag(xmlNode, depth);
		}
		else
