	case xtpToolTipRTF:
		return new CRichEditToolTip(this);

	case xtpToolTipLuna:
		return new CLunaToolTip(this);

	case xtpToolTipOffice2007:
		return new COffice2007ToolTip(this);

#ifndef _XTP_EXCLUDE_HTML
	case xtpToolTipHTML:
